-- FindMySpare v3: one network for every spare part of every machine.
-- Industries / machine types / part categories, multi-role businesses, trade
-- links, price lists, purchase orders, khata (ledger), counter bills, demand
-- search events, Fix service requests; products + machines become industry-aware.
-- Add-only: creates types/tables/indexes, adds columns and enum values, and
-- relaxes vehicles.reg_no to nullable (machines without plates). No drops,
-- renames or data deletion. Generated by drizzle-kit (production main schema →
-- this branch) and verified: old schema + this file == new schema (no diff).
--
-- Run once against production BEFORE deploying the v3 API, then seed taxonomy:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f drizzle/manual/0002_v3_network_every_industry.sql
--   bun --env-file=.env run src/scripts/seed-catalog.ts   (production-safe, idempotent)
BEGIN;
CREATE TYPE "public"."ledger_entry_type" AS ENUM('invoice', 'payment', 'credit_note', 'opening');
CREATE TYPE "public"."po_status" AS ENUM('sent', 'accepted', 'rejected', 'shipped', 'received', 'cancelled');
CREATE TYPE "public"."service_request_status" AS ENUM('open', 'accepted', 'completed', 'cancelled');
CREATE TYPE "public"."trade_link_status" AS ENUM('pending', 'active', 'blocked');
ALTER TYPE "public"."stock_movement_reason" ADD VALUE 'sale';
ALTER TYPE "public"."stock_movement_reason" ADD VALUE 'purchase';
CREATE TABLE "industries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"slug" varchar(40) NOT NULL,
	"name" varchar(80) NOT NULL,
	"tagline" varchar(160),
	"icon" varchar(40) DEFAULT 'engine' NOT NULL,
	"tint" varchar(9) DEFAULT '#FFF1EB' NOT NULL,
	"ink" varchar(9) DEFAULT '#A32D0C' NOT NULL,
	"identifier_label" varchar(40) DEFAULT 'Serial no.' NOT NULL,
	"sort_order" integer DEFAULT 100 NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	CONSTRAINT "industries_slug_unique" UNIQUE("slug")
);

CREATE TABLE "ledger_entries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"owner_id" uuid NOT NULL,
	"counterparty_id" uuid,
	"counterparty_name" varchar(160),
	"counterparty_phone" varchar(20),
	"type" "ledger_entry_type" NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"ref_type" varchar(20),
	"ref_id" uuid,
	"note" varchar(200),
	"method" varchar(20),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "machine_types" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"industry_id" uuid NOT NULL,
	"slug" varchar(60) NOT NULL,
	"name" varchar(80) NOT NULL,
	"attributes" jsonb DEFAULT '[]'::jsonb,
	"brands" jsonb DEFAULT '[]'::jsonb,
	"sort_order" integer DEFAULT 100 NOT NULL
);

CREATE TABLE "part_categories" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"industry_id" uuid NOT NULL,
	"name" varchar(80) NOT NULL,
	"icon" varchar(40) DEFAULT 'engine' NOT NULL,
	"sort_order" integer DEFAULT 100 NOT NULL
);

CREATE TABLE "price_list_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"price_list_id" uuid NOT NULL,
	"product_id" uuid NOT NULL,
	"price" numeric(12, 2) NOT NULL,
	"min_qty" integer DEFAULT 1 NOT NULL
);

CREATE TABLE "price_lists" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"owner_id" uuid NOT NULL,
	"name" varchar(80) NOT NULL,
	"discount_pct" numeric(5, 2) DEFAULT '0' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "purchase_orders" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"number" varchar(30) NOT NULL,
	"buyer_id" uuid NOT NULL,
	"seller_id" uuid NOT NULL,
	"status" "po_status" DEFAULT 'sent' NOT NULL,
	"lines" jsonb NOT NULL,
	"subtotal" numeric(14, 2) NOT NULL,
	"tax" numeric(14, 2) NOT NULL,
	"total" numeric(14, 2) NOT NULL,
	"payment_terms" varchar(20) DEFAULT 'credit' NOT NULL,
	"due_date" timestamp with time zone,
	"note" text,
	"seller_note" text,
	"tracking_note" varchar(200),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "sales_bills" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"seller_id" uuid NOT NULL,
	"number" varchar(30) NOT NULL,
	"customer_name" varchar(160),
	"customer_phone" varchar(20),
	"customer_id" uuid,
	"lines" jsonb NOT NULL,
	"subtotal" numeric(14, 2) NOT NULL,
	"tax" numeric(14, 2) NOT NULL,
	"total" numeric(14, 2) NOT NULL,
	"payment_mode" varchar(20) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "search_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"query" varchar(200),
	"industry_slug" varchar(40),
	"category" varchar(100),
	"brand" varchar(100),
	"model" varchar(100),
	"city" varchar(100),
	"result_count" integer DEFAULT 0 NOT NULL,
	"user_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "service_requests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"customer_id" uuid NOT NULL,
	"industry_slug" varchar(40) NOT NULL,
	"machine_type" varchar(80),
	"brand" varchar(100),
	"model" varchar(100),
	"vehicle_id" uuid,
	"problem" text NOT NULL,
	"city" varchar(100),
	"address" varchar(255),
	"phone" varchar(20),
	"preferred_time" varchar(60),
	"status" "service_request_status" DEFAULT 'open' NOT NULL,
	"garage_id" uuid,
	"job_card_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "trade_links" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"supplier_id" uuid NOT NULL,
	"buyer_id" uuid NOT NULL,
	"status" "trade_link_status" DEFAULT 'pending' NOT NULL,
	"requested_by" uuid NOT NULL,
	"price_list_id" uuid,
	"credit_limit" numeric(14, 2) DEFAULT '0' NOT NULL,
	"credit_days" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE "vehicles" ALTER COLUMN "reg_no" DROP NOT NULL;
ALTER TABLE "users" ADD COLUMN "business_roles" jsonb DEFAULT '[]'::jsonb;
ALTER TABLE "users" ADD COLUMN "industries" jsonb DEFAULT '[]'::jsonb;
ALTER TABLE "products" ADD COLUMN "industry_slug" varchar(40) DEFAULT 'automotive' NOT NULL;
ALTER TABLE "products" ADD COLUMN "machine_type" varchar(80);
ALTER TABLE "products" ADD COLUMN "attributes" jsonb DEFAULT '{}'::jsonb;
ALTER TABLE "products" ADD COLUMN "moq" integer DEFAULT 1 NOT NULL;
ALTER TABLE "garages" ADD COLUMN "industry_slugs" jsonb DEFAULT '["automotive"]'::jsonb;
ALTER TABLE "vehicles" ADD COLUMN "industry_slug" varchar(40) DEFAULT 'automotive' NOT NULL;
ALTER TABLE "vehicles" ADD COLUMN "machine_type" varchar(80);
ALTER TABLE "vehicles" ADD COLUMN "serial_no" varchar(60);
ALTER TABLE "ledger_entries" ADD CONSTRAINT "ledger_entries_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "ledger_entries" ADD CONSTRAINT "ledger_entries_counterparty_id_users_id_fk" FOREIGN KEY ("counterparty_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "machine_types" ADD CONSTRAINT "machine_types_industry_id_industries_id_fk" FOREIGN KEY ("industry_id") REFERENCES "public"."industries"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "part_categories" ADD CONSTRAINT "part_categories_industry_id_industries_id_fk" FOREIGN KEY ("industry_id") REFERENCES "public"."industries"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "price_list_items" ADD CONSTRAINT "price_list_items_price_list_id_price_lists_id_fk" FOREIGN KEY ("price_list_id") REFERENCES "public"."price_lists"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "price_list_items" ADD CONSTRAINT "price_list_items_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "price_lists" ADD CONSTRAINT "price_lists_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "purchase_orders" ADD CONSTRAINT "purchase_orders_buyer_id_users_id_fk" FOREIGN KEY ("buyer_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "purchase_orders" ADD CONSTRAINT "purchase_orders_seller_id_users_id_fk" FOREIGN KEY ("seller_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "sales_bills" ADD CONSTRAINT "sales_bills_seller_id_users_id_fk" FOREIGN KEY ("seller_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "sales_bills" ADD CONSTRAINT "sales_bills_customer_id_users_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "service_requests" ADD CONSTRAINT "service_requests_customer_id_users_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "trade_links" ADD CONSTRAINT "trade_links_supplier_id_users_id_fk" FOREIGN KEY ("supplier_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "trade_links" ADD CONSTRAINT "trade_links_buyer_id_users_id_fk" FOREIGN KEY ("buyer_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "trade_links" ADD CONSTRAINT "trade_links_requested_by_users_id_fk" FOREIGN KEY ("requested_by") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "ledger_owner_idx" ON "ledger_entries" USING btree ("owner_id");
CREATE INDEX "ledger_counterparty_idx" ON "ledger_entries" USING btree ("owner_id","counterparty_id","counterparty_phone");
CREATE UNIQUE INDEX "machine_types_industry_slug_uq" ON "machine_types" USING btree ("industry_id","slug");
CREATE UNIQUE INDEX "part_categories_industry_name_uq" ON "part_categories" USING btree ("industry_id","name");
CREATE UNIQUE INDEX "price_list_items_pair_uq" ON "price_list_items" USING btree ("price_list_id","product_id");
CREATE INDEX "price_lists_owner_idx" ON "price_lists" USING btree ("owner_id");
CREATE INDEX "po_buyer_idx" ON "purchase_orders" USING btree ("buyer_id");
CREATE INDEX "po_seller_idx" ON "purchase_orders" USING btree ("seller_id");
CREATE INDEX "sales_bills_seller_idx" ON "sales_bills" USING btree ("seller_id");
CREATE INDEX "search_events_created_idx" ON "search_events" USING btree ("created_at");
CREATE INDEX "service_requests_status_idx" ON "service_requests" USING btree ("status","industry_slug");
CREATE INDEX "service_requests_customer_idx" ON "service_requests" USING btree ("customer_id");
CREATE UNIQUE INDEX "trade_links_pair_uq" ON "trade_links" USING btree ("supplier_id","buyer_id");
CREATE INDEX "trade_links_buyer_idx" ON "trade_links" USING btree ("buyer_id");
CREATE INDEX "products_industry_idx" ON "products" USING btree ("industry_slug");
COMMIT;
